  (gen_random_uuid(), 1, 'Cost', 'Üretim adedi değişse de yönetici maaşı aynı kalıyor. Bütçe modelinde bu gideri nasıl sınıflandırırsın?', 'İlgili kapasite aralığında sabit maliyet olarak kaydederim.', 'Her ürünle bire bir artan değişken maliyet olarak dağıtırım.', 'Gelir kalemi sayıp toplam maliyetten bağımsız tutarım.', 'Üretim durduğunda otomatik sıfırlanan birim maliyet kabul ederim.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Cost', 'Her üretilen cihaz için aynı miktarda bağlantı parçası tüketiliyor. Maliyeti nasıl modelliyorsun?', 'Üretim hacmiyle birlikte değişen değişken maliyet olarak modellerim.', 'Üretim miktarından bağımsız yıllık sabit gider sayarım.', 'Parça alımını dönem sonu hurda değeri olarak gösteririm.', 'Tüketilen parçaları maliyet hesabına hiç katmam.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Cash Flow', 'Bir proje nakit akış diyagramında müşteriden alınan ödeme gösterilecek. Oku nasıl yerleştirirsin?', 'Nakit girişini zaman ekseninde yukarı yönlü okla gösteririm.', 'Ödemeyi gider gibi aşağı yönlü okla gösteririm.', 'Tutarı zaman noktası olmadan eksenin dışında bırakırım.', 'Gelir ile gideri aynı yönde çizip işaret ayrımını kaldırırım.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Cash Flow', 'Yeni makine için bugün ödenen satın alma bedelini projeye ekliyorsun. Hangi kayıt uygundur?', 'Sıfırıncı dönemde negatif ilk yatırım nakit akışı kaydederim.', 'Makine bedelini son yılda pozitif hurda değeri olarak yazarım.', 'İlk ödemeyi yıllık gelirlerin arasına eşit biçimde dağıtırım.', 'Bugünkü ödemeyi zaman değeri hesabının dışında bırakırım.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Present Value', 'İki yıl sonraki bakım ödemesini bugünkü bütçeyle karşılaştıracaksın. Ne yaparsın?', 'Gelecekteki ödemeyi uygun faiz oranıyla bugüne indirgerim.', 'Ödemeyi faiz ekleyerek daha ileri bir tarihe taşırım.', 'İki yıl sonraki tutarı bugünkü tutarla doğrudan eşit sayarım.', 'Bakım giderini nakit çıkışı yerine gelir olarak kaydederim.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Future Value', 'Bugün ayrılan yenileme fonunun dört yıl sonraki değerini bulmalısın. Hangi yönü kullanırsın?', 'Bugünkü tutarı dönemler boyunca faizle geleceğe taşırım.', 'Gelecekteki tutarı bugüne indirgeme işlemi uygularım.', 'Tutarı yalnızca dönem sayısına bölerek gelecek değer bulurum.', 'Faiz oranını yok sayıp fonun değerini sabit kabul ederim.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Compound Interest', 'Fonun faizi her dönem anaparaya eklenip sonraki dönemde yeniden faiz kazanıyor. Hangi modeli seçersin?', 'Faizin de faiz kazandığı bileşik faiz modelini kullanırım.', 'Her dönem yalnızca ilk anaparaya faiz yazan doğrusal model kullanırım.', 'Faizi nakit akışından çıkarıp yalnızca dönem sayısını izlerim.', 'Her dönemin birikimini silip sadece son dönem faizini tutarım.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Interest', 'Nakit akışları aylık, verilen faiz oranı ise yıllık. Hesaba başlamadan hangi kontrolü yaparsın?', 'Faiz oranı ile nakit akışı dönemlerini aynı zaman birimine getiririm.', 'Yıllık oranı aylık akışlara dönüşüm yapmadan doğrudan uygularım.', 'Ay sayısını yıl sayısı kabul edip ödeme tarihlerini değiştirmem.', 'Dönem uyumsuzluğunu gidermek için bütün faiz etkisini sıfırlarım.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'MARR', 'Bir yatırımın getirisi şirketin kabul ettiği en düşük seviyeye göre değerlendirilecek. Hangi eşiği kullanırsın?', 'Minimum kabul edilebilir getiri oranını, yani MARR değerini kullanırım.', 'Yalnızca projenin en yüksek yıllık gelirini eşik kabul ederim.', 'Hurda değerini getiri oranı yerine karşılaştırma ölçütü yaparım.', 'Sermaye beklentisini yok sayıp pozitif gelir bulunan her projeyi seçerim.', 'engineering_economics', 1),
  (gen_random_uuid(), 2, 'Annuity', 'Bakım sözleşmesi beş yıl boyunca yıl sonunda eşit ödeme üretiyor. Akışı nasıl ele alırsın?', 'Eşit tutarlı ve eşit aralıklı bir yıllık seri olarak modellerim.', 'Bütün ödemeleri sıfırıncı dönemde yapılmış tek tutar sayarım.', 'Ödeme sayısını dikkate almadan yalnızca son ödemeyi kullanırım.', 'Eşit ödemeleri farklı tarihlerdeymiş gibi rastgele dağıtırım.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Salvage Value', 'Makine ekonomik ömrünün sonunda satılabilecek. Bu tutarı nakit akışına nasıl eklersin?', 'Ömür sonunda pozitif hurda değeri nakit girişi olarak eklerim.', 'Hurda değerini ilk yatırım anında ek bir nakit çıkışı sayarım.', 'Satış tutarını yıllık işletme maliyetine eşit olarak bölerim.', 'Makine satılacak olsa da son dönem değerini tamamen yok sayarım.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Depreciation', 'Bir varlığın amortismana tabi değeri her yıl eşit azalacak. Hangi yöntemi seçersin?', 'Her yıl eşit amortisman ayıran düz çizgi yöntemini kullanırım.', 'İlk yıllarda daha yüksek oran uygulayan çift azalan yöntemi kullanırım.', 'Amortismanı yalnızca satış yılındaki nakit gider olarak kaydederim.', 'Varlığın değerini ekonomik ömür boyunca hiç azaltmam.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Depreciation', 'Şirket vergi hesabında varlığın ilk yıllarında daha yüksek amortisman ayırmak istiyor. Hangi yaklaşım uygundur?', 'Çift azalan bakiyeler gibi hızlandırılmış bir yöntem kullanırım.', 'Her yıl eşit tutar ayıran düz çizgi yöntemini hızlandırılmış sayarım.', 'İlk yıllarda hiç amortisman ayırmayıp tamamını son yıla bırakırım.', 'Amortisman yerine ilk yatırım maliyetini yıllık gelir olarak gösteririm.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Economic Life', 'Bir makine fiziksel olarak çalışsa da işletme maliyeti hızla yükseliyor. Değiştirme kararında hangi süreyi izlersin?', 'Ekonomik açıdan kullanmanın uygun kaldığı ekonomik ömrü değerlendiririm.', 'Yalnızca cihaz tamamen bozulana kadarki fiziksel ömrü kullanırım.', 'Garanti süresini bütün alternatifler için ekonomik ömür kabul ederim.', 'İşletme ve yenileme maliyetlerini incelemeden ömrü sınırsız sayarım.', 'engineering_economics', 1),
  (gen_random_uuid(), 2, 'Alternative Analysis', 'Aynı işi yapan üç makineden yalnızca biri satın alınabilecek. Alternatifleri nasıl tanımlarsın?', 'Birbirini dışlayan alternatifler olarak tek seçim analizi yaparım.', 'Üç makinenin de birlikte alınacağı bağımsız projeler gibi değerlendiririm.', 'Her makineyi diğerlerinin nakit akışını etkilemeyen zorunlu yatırım sayarım.', 'Seçim kısıtını kaldırıp bütçe yetmese de bütün makineleri kabul ederim.', 'engineering_economics', 1),
  (gen_random_uuid(), 1, 'Interest', 'Yıllık nominal oran yüzde 12 ve faiz altı ayda bir bileşikleniyor. Dönem hesabını nasıl kurarsın?', 'Altı aylık oranı kullanır, yıl sayısını ikiyle çarparak dönem sayısını bulurum.', 'Yüzde 12 oranını her altı aylık döneme aynen uygularım.', 'Yıllık oranı ikiye bölmeden dönem sayısını yarıya indiririm.', 'Bileşiklenme sıklığını yok sayıp bütün akışları tek dönem kabul ederim.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Present Value', 'Farklı yıllarda oluşacak üç bakım giderinin bugünkü karşılığını istiyorsun. Nasıl hesaplarsın?', 'Her gideri kendi tarihinden bugüne indirger ve bugünkü değerleri toplarım.', 'Bütün giderlere en uzak tarihin iskonto katsayısını uygularım.', 'Tarihleri yok sayıp nominal tutarları doğrudan toplarım.', 'Giderleri pozitif gelir sayıp bugünkü proje değerini yükseltirim.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Future Value', 'Haftalara dağılmış gelir ve giderleri on birinci hafta sonunda birleştireceksin. Nasıl ilerlersin?', 'Her akışı kendi tarihinden hedef haftaya kadar bileşik olarak taşırım.', 'Bütün akışlara on bir tam dönem faiz uygulayıp çıkış tarihlerini yok sayarım.', 'Yalnızca son haftadaki akışı gelecek değer hesabına dahil ederim.', 'Gelir ve giderlerin işaretlerini kaldırıp mutlak değerlerini biriktiririm.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Present Worth', 'Bağımsız bir projenin MARR ile hesaplanan bugünkü değeri sıfırdan büyük. Kararın ne olur?', 'Diğer kısıtlar sağlanıyorsa proje ekonomik eşiği geçtiği için kabul ederim.', 'Pozitif bugünkü değeri projenin MARR altında kaldığı şeklinde yorumlarım.', 'Bugünkü değerin işaretini yok sayıp yalnızca ilk yatırım tutarına bakarım.', 'Pozitif sonucu nakit çıkışı kabul edip projeyi otomatik reddederim.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Present Worth', 'Aynı hizmeti veren ve ömürleri eşit iki makinenin yalnızca maliyetleri farklı. PW kararını nasıl verirsin?', 'MARR ile bugüne indirgenmiş toplam maliyeti daha düşük olanı seçerim.', 'İlk yatırım tutarı yüksek olanı diğer giderleri incelemeden seçerim.', 'Maliyetlerin işaretini kaldırıp bugünkü değeri en yüksek olan gideri seçerim.', 'İşletme ve hurda akışlarını dışarıda bırakıp yalnızca satın alma fiyatını karşılaştırırım.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Equivalent Annual Cost', 'Aynı görevi yapan makinelerin ekonomik ömürleri farklı. Karşılaştırmayı nasıl adil kurarsın?', 'Akışları ortak bir çalışma süresine veya eşdeğer yıllık değere dönüştürürüm.', 'Her makinenin toplam nominal giderini ömür farkını yok sayarak karşılaştırırım.', 'Kısa ömürlü makinenin eksik yıllarını sıfır maliyetli kabul ederim.', 'Yalnızca uzun ömürlü olduğu için diğer ölçütlere bakmadan onu seçerim.', 'engineering_economics', 2),
  (gen_random_uuid(), 1, 'Cash Flow', 'Makine yılda gelir üretiyor ve aynı dönemde işletme gideri çıkarıyor. Yıllık net akışı nasıl bulursun?', 'Yıllık gelirden aynı dönemin işletme giderini çıkarırım.', 'Gelir ile gideri işaretlerine bakmadan toplayıp net giriş sayarım.', 'İşletme giderini ilk yatırım maliyetine ekleyip yıllık akışı sıfırlarım.', 'Yıllık geliri gider kabul edip işletme giderini pozitif yazarım.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Tax', 'Amortisman nakit ödeme olmadığı halde vergi sonrası analizde neden önemlidir?', 'Vergiye tabi geliri ve dolayısıyla ödenecek vergiyi etkilediği için hesaba katarım.', 'Kasadan her yıl aynı tutarda çıktığı için işletme gideri olarak eklerim.', 'Vergi oranını değiştirdiği için doğrudan MARR yerine kullanırım.', 'Nakit dışı olduğu için vergi hesabından da tamamen çıkarırım.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Salvage Value', 'PW tablosunda makinenin son yıl satış değeri unutulmuş. Nasıl düzeltirsin?', 'Son döneme hurda değerini uygun işaretle ekleyip bugüne indirgerim.', 'Hurda değerini sıfırıncı dönemde satın alma maliyetine eklerim.', 'Satış değerini her yıl tekrarlanan gelir gibi bütün dönemlere yazarım.', 'Son yıl olduğu için faiz hesabına hiçbir biçimde dahil etmem.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Cost', 'Bakım giderinin bir bölümü sözleşme bedeli, kalanı çalışma saatiyle artıyor. Modeli nasıl kurarsın?', 'Gideri sabit ve kullanıma bağlı değişken bileşenlere ayırırım.', 'Bütün gideri yalnızca sabit kabul edip kullanım etkisini yok sayarım.', 'Bütün gideri yalnızca değişken kabul edip sözleşme bedelini sıfırlarım.', 'Bakım giderini makinenin hurda değeri olarak sınıflandırırım.', 'engineering_economics', 2),
  (gen_random_uuid(), 1, 'Cash Flow', 'Ödeme sözleşmede her haftanın sonunda yapılıyor. Diyagramdaki ilk ödeme hangi noktada olmalı?', 'İlk haftanın sonunu gösteren birinci dönem noktasına yerleştiririm.', 'Sözleşme imzalanır imzalanmaz sıfırıncı döneme yerleştiririm.', 'İlk ödemeyi ikinci haftanın sonuna kaydırıp bir dönem geciktiririm.', 'Hafta sonu bilgisini yok sayıp bütün ödemeleri aynı noktaya çizerim.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Incremental IRR', 'Birbirini dışlayan yatırımlarda artan IRR analizi yapılacak. İlk hazırlık adımın ne olur?', 'Alternatifleri ilk yatırım büyüklüğüne göre sıralayıp fark nakit akışlarını kurarım.', 'Alternatifleri adlarına göre sıralayıp tek tek IRR değerlerini toplarım.', 'En yüksek gelirli seçeneği savunucu yapıp yatırım farkını hesaplamam.', 'Bütün alternatiflerin akışlarını tek projede birleştirip seçim kısıtını kaldırırım.', 'engineering_economics', 2),
  (gen_random_uuid(), 3, 'Incremental IRR', 'Bir makinenin tek başına IRR değeri en yüksek görünüyor. Bu bilgi seçim için neden yeterli değildir?', 'Ek yatırımın sağladığı fark getiri MARR ile karşılaştırılmadan üstün seçenek belirlenemez.', 'En yüksek IRR her durumda en yüksek ilk maliyet anlamına geldiği için yetersizdir.', 'IRR yalnızca hurda değerini ölçtüğü için yıllık gelirleri kapsamaz.', 'Birbirini dışlayan seçeneklerde ekonomik karşılaştırma yapılamayacağı için yetersizdir.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'MARR', 'Aynı nakit akışları için şirketin MARR değeri yükseldi. Uzak gelecekteki gelirlerin bugünkü etkisi nasıl değişir?', 'Daha yüksek iskonto nedeniyle uzak gelirlerin bugünkü değeri azalır.', 'MARR yükseldikçe bütün gelecek gelirlerin bugünkü değeri artar.', 'MARR yalnızca ilk yatırım tutarını değiştirir, gelecek akışları etkilemez.', 'İskonto oranı yükselince gelirlerin tarihleri sıfırıncı döneme taşınır.', 'engineering_economics', 2),
  (gen_random_uuid(), 2, 'Depreciation', 'Amortisman çizelgesi varlığın beklenen hurda değerinin altına iniyor. Nasıl düzeltirsin?', 'Toplam amortismanı ilk maliyet ile hurda değeri arasındaki tutarı aşmayacak biçimde sınırlarım.', 'Negatif defter değerine ulaşana kadar aynı amortismanı sürdürürüm.', 'Hurda değerini yıllık amortisman gideri olarak her döneme eklerim.', 'Defter değeri sınırını kaldırıp toplam amortismanı ilk maliyetin üstüne çıkarırım.', 'engineering_economics', 2),
  (gen_random_uuid(), 3, 'Tax', 'Üç makine farklı amortisman yöntemleri ve ekonomik ömürlerle sunuluyor. Vergi sonrası seçimi nasıl yaparsın?', 'Her alternatif için vergiye tabi geliri, vergiyi ve zamanlanmış net nakit akışlarını ayrı kurarım.', 'Amortisman yöntemlerini yok sayıp yalnızca vergi öncesi brüt gelirleri karşılaştırırım.', 'Vergi oranını ilk yatırım maliyetinden bir kez düşüp sonraki yılları vergi dışı bırakırım.', 'Bütün makinelerin amortismanını eşit kabul edip ekonomik ömür farklarını silerim.', 'engineering_economics', 3),
  (gen_random_uuid(), 3, 'Incremental IRR', 'Daha pahalı aday ile mevcut savunucu arasındaki artan IRR, MARR değerinin üstünde çıktı. Kararın ne olur?', 'Fark akışı geçerliyse ek yatırım MARR''ı geçtiği için daha pahalı adayı seçerim.', 'Artan IRR yüksek olduğu için daha düşük yatırımlı savunucuyu seçerim.', 'Artan IRR değerini iki alternatifin yıllık gelir toplamı olarak yorumlarım.', 'MARR karşılaştırmasını yok sayıp yalnızca adayın bireysel IRR değerine bakarım.', 'engineering_economics', 3),
  (gen_random_uuid(), 3, 'IRR', 'Bir projenin nakit akışı birden fazla kez işaret değiştiriyor ve birden çok IRR sonucu oluşuyor. Nasıl karar verirsin?', 'IRR sonucunu tek başına kullanmayıp MARR ile bugünkü değer analizine başvururum.', 'IRR sonuçlarının en büyüğünü hiçbir ek kontrol yapmadan seçerim.', 'Bütün IRR köklerini toplayıp proje getirisi olarak MARR ile karşılaştırırım.', 'İşaret değişimlerini silerek nakit akışını tek yönlü hale getiririm.', 'engineering_economics', 3),
  (gen_random_uuid(), 3, 'Alternative Analysis', 'Dört ve üç yıllık iki makine belirli bir yedi yıllık proje için değerlendiriliyor. Ömür farkını nasıl yönetirsin?', 'Yedi yıllık çalışma dönemindeki yenilemeleri ve dönem sonu kalan değerleri açıkça modellerim.', 'Her makinenin ilk ömrünü karşılaştırıp proje döneminin kalanını maliyetsiz sayarım.', 'Ömürleri ortak değil diye bütün nakit akışlarını aynı yıl sayısına bölerim.', 'Uzun ömürlü makineyi yenileme ve kalan değer hesabı yapmadan otomatik seçerim.', 'engineering_economics', 3),
  (gen_random_uuid(), 3, 'Depreciation', 'İki yöntem toplamda aynı amortismana ulaşıyor fakat biri indirimi ilk yıllara taşıyor. PW etkisini nasıl yorumlarsın?', 'Vergi indirimi kullanılabiliyorsa erken tasarrufların zaman değerini ayrıca hesaplarım.', 'Toplam amortisman eşit olduğundan vergi tasarruflarının zamanını tamamen önemsiz sayarım.', 'Erken amortismanı doğrudan aynı tutarda nakit geliri olarak iki kez eklerim.', 'Amortisman zamanlamasını incelemeden bütün vergi sonrası PW değerlerini eşit ilan ederim.', 'engineering_economics', 3),
  (gen_random_uuid(), 3, 'Compound Interest', 'Yıllık nominal yüzde 12 oran altı ayda bir bileşikleniyor; rapor yıllık etkin oran istiyor. Ne yaparsın?', 'Altı aylık dönem oranını iki dönem bileşikleyerek yıllık etkin oranı bulurum.', 'Nominal yüzde 12 değerini dönüşüm yapmadan etkin oran diye raporlarım.', 'Altı aylık oranı ikiyle çarpıp bileşiklenme etkisini yok sayarım.', 'Yıllık etkin oranı dönem sayısına bölerek altı aylık orandan daha düşük bulurum.', 'engineering_economics', 3),
  (gen_random_uuid(), 3, 'Cash Flow', 'Ekip üçüncü yıl sonundaki ödemeyi üçüncü yıl başına yazmış. Ekonomik sonuç neden bozulur?', 'Akış bir dönem erken indirgenir ve bugünkü değeri olması gerekenden yüksek hesaplanır.', 'Ödeme tutarı değişmediği için zaman kaymasının ekonomik sonucu olmaz.', 'Akış bir dönem geç indirgenir ve bugünkü değeri otomatik olarak sıfırlanır.', 'Zaman hatası yalnızca nakit girişlerini etkiler, giderlerin PW değerini etkilemez.', 'engineering_economics', 3),
  (gen_random_uuid(), 3, 'Incremental IRR', 'Üç yatırım artan maliyete göre sıralandı; ilk karşılaştırmada pahalı seçenek savunucuyu geçti. Sonraki adım nedir?', 'Kazanan seçeneği yeni savunucu yapıp sıradaki adayın fark nakit akışını karşılaştırırım.', 'İlk kazananı kesin seçip daha pahalı seçenekleri analizden çıkarırım.', 'Kaybeden seçeneği savunucu tutup aynı fark hesabını tekrarlarım.', 'Kalan alternatiflerin bireysel IRR değerlerini toplayıp tek aday oluştururum.', 'engineering_economics', 3),
  (gen_random_uuid(), 3, 'Present Worth', 'Bir alternatifin PW hesabında ilk yatırım unutulmuş ve sonuç güçlü biçimde pozitif görünüyor. Ne yaparsın?', 'Sıfırıncı dönem yatırım çıkışını ekleyip bütün analizi yeniden hesaplarım.', 'Pozitif sonuç karar vermeye yettiği için eksik yatırımı yalnızca dipnota yazarım.', 'İlk yatırımı son yıl geliri olarak ekleyip işaret dengesini koruduğumu varsayarım.', 'Eksik maliyeti diğer alternatiflerin PW değerlerinden çıkararak düzeltirim.', 'engineering_economics', 3),
